import type { IQueryPanelApi } from "../core/api-types";
import type { ParamRecord, QueryEngine } from "../core/query-engine";

/**
 * A query previously generated by the server (`ask()` / `modifyChart()` return its `queryId`).
 */
export interface ResolvedQuery {
	queryId: string;
	sql: string;
	/** Bind values keyed for the attached adapter (numeric + named keys). */
	params: ParamRecord;
	/** Raw parameter metadata as stored by the server. */
	paramMetadata: Array<Record<string, unknown>>;
	dialect: string;
}

interface ServerResolvedQuery {
	queryId: string;
	sql: string;
	params?: Array<Record<string, unknown>>;
	dialect: string;
}

export interface ResolveQueryOptions {
	tenantId: string;
	userId?: string;
	scopes?: string[];
}

/**
 * Loads the server-stored SQL and bind params for a `queryId`.
 *
 * The lookup is scoped by the authenticated organization and tenant on the server, so an
 * id from another tenant (or one that never existed) is rejected. Callers should use the
 * returned SQL/params and ignore any client-supplied values.
 */
export async function resolveQuery(
	client: IQueryPanelApi,
	queryEngine: QueryEngine,
	queryId: string,
	options: ResolveQueryOptions,
	signal?: AbortSignal,
): Promise<ResolvedQuery> {
	const response = await client.get<ServerResolvedQuery>(
		`/v2/queries/${encodeURIComponent(queryId)}`,
		options.tenantId,
		options.userId,
		options.scopes,
		signal,
	);

	const paramMetadata = Array.isArray(response.params) ? response.params : [];
	return {
		queryId: response.queryId,
		sql: response.sql,
		params: queryEngine.mapGeneratedParams(paramMetadata),
		paramMetadata,
		dialect: response.dialect,
	};
}

/**
 * Mark a stored query as EXECUTED after local SQL succeeds.
 * Best-effort: never fails the caller. No-op when the row is already SUCCESS.
 */
export async function markQueryExecuted(
	client: IQueryPanelApi,
	queryId: string,
	options: ResolveQueryOptions,
	signal?: AbortSignal,
): Promise<void> {
	try {
		await client.post(
			`/v2/queries/${encodeURIComponent(queryId)}/executed`,
			{},
			options.tenantId,
			options.userId,
			options.scopes,
			signal,
		);
	} catch {
		// Headless metrics must not break execution.
	}
}
